mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.HAP_CREDIT_AMT as hapCreditAmt, C.CUSTOMER_NAME as customerName
,A.INSTITUTION_CODE as institutionCode
,D.INSITITUTE_CODE as insitituteCode FROM CREDIT_LINES A INNER JOIN CREDIT_MST_INFO B on A.CREDIT_MST_ID=B.SEQNO and B.CREDIT_INFO_TYPE in ('01') left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID
A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}

     select nvl(sum(base99.count),0) from (
       SELECT
	 	count(1) as count,
	 	A.INSTITUTION_CODE as institutionCode
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
        /** modify by yanya on 20190930 去除主体客户编号为空判断
         and PARENT_CUSTOMER_ID IS NULL 
         **/

      and to_char(VDATE,'yyyy-MM-dd')<= #{vmdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')>=#{vmdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

		GROUP BY A.INSTITUTION_CODE
	) base99

		where base99.institutionCode in

				#{institutionCode}

     select nvl(sum(base99.count),0) from (
       SELECT
	 	count(1) as count,
	 	A.INSTITUTION_CODE as institutionCode
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
        /** modify by yanya on 20190930 去除主体客户编号为空判断
         and PARENT_CUSTOMER_ID IS NULL 
          **/

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

		GROUP BY A.INSTITUTION_CODE
	) base99

		where base99.institutionCode in

				#{institutionCode}

    select nvl(sum(base99.count),0) from (
       SELECT
	 	count(1) as count,
	 	A.INSTITUTION_CODE as institutionCode
	 FROM 
	 	CREDIT_LINES A
        where PFLSH = #{pflsh,jdbcType=VARCHAR}

			 and  SEQNO <> #{seqno}


			and CREDIT_MST_ID=#{creditMstId}

		GROUP BY A.INSTITUTION_CODE
	) base99

			where base99.institutionCode in

				#{institutionCode}

SELECT distinct CUSTOMER_ID AS id, CUSTOMER_NAME AS text FROM MST_CUSTOMER_INFO where CUSTOMER_TYPE = #{customerType,jdbcType=VARCHAR}
AND (CUSTOMER_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) or CUSTOMER_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND CUSTOMER_ID = #{initValue,jdbcType=VARCHAR}

		SELECT count(1)
		FROM CREDIT_LINES A
		where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR}

        and A.PFLSH = #{pflsh,jdbcType=VARCHAR}
		and  A.Hap_Credit_Amt>0

select CLD1.* from CREDIT_LINES_DEAL CLD1
left join CREDIT_LINES CL1 on CL1.SEQNO = CLD1.SEQNO
WHERE CL1.VDATE = (select max(VDATE) from CREDIT_LINES CL2 WHERE CL1.CREDIT_MST_ID = CL2.CREDIT_MST_ID AND CL1.CUSTOMER_ID = CL2.CUSTOMER_ID

	and CL2.vdate < #{vdate, jdbcType=DATE}

)

	and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


	AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

select nvl(CL1.HAP_CREDIT_AMT,0) from CREDIT_LINES CL1
WHERE CL1.VDATE = (select max(VDATE) from CREDIT_LINES CL2 WHERE CL1.CREDIT_MST_ID = CL2.CREDIT_MST_ID AND CL1.CUSTOMER_ID = CL2.CUSTOMER_ID

	and CL2.vdate < #{vdate, jdbcType=DATE}

)

	and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


	AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

        select * from CREDIT_LINES CL1
        WHERE 1=1

            and CL1.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


            AND CL1.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


			AND to_char(CL1.VDATE,'yyyy-MM-dd')  = #{vdate, jdbcType=VARCHAR}
